const http=require('node:http');const {portfolio:seed}=require('./data/portfolio');const store=require('./data/store');
const PORT=Number(process.env.PORT||3000);store.seed(seed);store.applyPortfolioEnhancements();const json=(res,code,x)=>{const b=JSON.stringify(x);res.writeHead(code,{'Content-Type':'application/json; charset=utf-8','Content-Length':Buffer.byteLength(b),'Cache-Control':'no-store'});res.end(b)};
const body=req=>new Promise((ok,no)=>{let b='';req.on('data',c=>b+=c);req.on('end',()=>{try{ok(b?JSON.parse(b):{})}catch(e){no(e)}});req.on('error',no)});
function vm(){const p=store.portfolio(),as=store.assessments(),latest=new Map();for(const a of as)if(!latest.has(a.entityId))latest.set(a.entityId,a);const domains=p.domains.map(d=>({...d,services:p.services.filter(s=>s.domainId===d.id).map(s=>({...s,offerings:p.offerings.filter(o=>o.serviceId===s.id).map(o=>({...o,assessment:latest.get(o.id)||null,products:p.relationships.filter(r=>r.offeringId===o.id).map(r=>({...p.products.find(x=>x.id===r.productId),relationship:r})).filter(x=>x.id)}))}))}));const offerings=domains.flatMap(d=>d.services.flatMap(s=>s.offerings.map(o=>({...o,domainName:d.name,serviceName:s.name}))));const valueMap=new Map(store.offeringValues().map(v=>[v.offeringId,v]));for(const o of offerings)o.value=valueMap.get(o.id)||null;for(const d of domains)for(const svc of d.services)for(const o of svc.offerings)o.value=valueMap.get(o.id)||null;return {...p,domains,offerings,assessments:as,actions:store.actions(),decisions:store.decisions(),queue:store.queue(),rationalization:store.rationalization(),offeringValues:store.offeringValues(),campaign:store.assessmentCampaign(),storage:store.info()}}
const HTML=String.raw`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enterprise Services Portfolio</title><style>
:root{--n:#071d3b;--b:#1456e0;--bg:#f4f7fb;--p:#fff;--bd:#dce4ee;--t:#10243e;--m:#68788c;--g:#188657;--y:#a96f00;--r:#c33d4d;--pu:#7147c7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.side{position:fixed;width:265px;inset:0 auto 0 0;background:var(--n);color:#fff;padding:24px 13px;overflow:auto}.brand{font-weight:800;padding:0 12px 22px}.brand small{display:block;color:#9aacbf;margin-top:8px}.side button{width:100%;border:0;background:none;color:#bdc9d6;text-align:left;padding:10px 12px;border-radius:6px;margin:2px 0}.side button.active,.side button:hover{background:var(--b);color:#fff}.main{margin-left:265px}.top{height:64px;background:#fff;border-bottom:1px solid var(--bd);padding:22px 30px;color:var(--m);font-size:12px}.content{padding:34px;max-width:1600px;margin:auto}.hero{display:flex;justify-content:space-between;gap:20px}.hero h1{margin:0 0 8px}.hero p{color:var(--m);margin:0}.k{color:var(--b);font-size:10px;font-weight:800;letter-spacing:.12em}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.card,.panel{background:#fff;border:1px solid var(--bd);border-radius:8px;box-shadow:0 5px 18px #10243e0d}.card{padding:18px}.card strong{display:block;font-size:26px}.card span{font-size:10px;color:var(--m)}.panel{padding:20px;margin:18px 0}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin:18px 0}.tabs button,.btn{border:1px solid var(--bd);background:#fff;border-radius:6px;padding:8px 10px;font-size:10px}.tabs button.active,.btn.primary{background:var(--b);color:#fff}.table{overflow:auto;background:#fff;border:1px solid var(--bd);border-radius:8px}table{width:100%;border-collapse:collapse;font-size:11px}th{background:#f8fafc;color:var(--m);font-size:9px;text-transform:uppercase;text-align:left;padding:10px}td{padding:11px;border-top:1px solid #edf1f5;vertical-align:top}.tag{display:inline-block;padding:4px 7px;border-radius:12px;background:#edf2f7;font-size:9px}.Critical{color:var(--r);font-weight:800}.High{color:#b65d00;font-weight:800}.Medium{color:var(--b);font-weight:800}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.wide{grid-column:span 2}.full{grid-column:1/-1}label{display:block;font-size:8px;font-weight:800;text-transform:uppercase;color:var(--m);margin-bottom:5px}input,select,textarea{width:100%;border:1px solid var(--bd);border-radius:6px;padding:8px;background:#fff}textarea{min-height:70px}.list{max-height:300px;overflow:auto}.item{padding:8px 0;border-bottom:1px solid var(--bd);font-size:10px}.link{border:0;background:none;color:var(--b);padding:0;font-weight:700}.notice{background:#fff3cf;padding:10px;border-radius:6px;color:#795400;font-size:10px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.navgroup{padding:18px 12px 6px;color:#71869f;font-size:9px;font-weight:800;letter-spacing:.12em}.domainCards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.domainCard{padding:18px;text-align:left;border-top:3px solid var(--b)}.domainCard h3{margin:12px 0 7px}.domainCard p{color:var(--m);font-size:11px;line-height:1.5;min-height:52px}.pulse{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.pulse .panel{margin:0}.barrow{display:grid;grid-template-columns:100px 1fr 28px;gap:8px;align-items:center;margin:10px 0;font-size:10px}.bar{height:7px;background:#edf1f5;border-radius:4px;overflow:hidden}.fill{height:100%;background:var(--b)}.serviceBlock{margin:28px 0}.serviceHead{display:flex;align-items:end;justify-content:space-between;margin-bottom:10px}.offeringCards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.offeringCard{padding:16px}.offeringCard h4{margin:10px 0}.meta{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--bd);margin-top:12px}.meta div{padding:9px 4px}.meta div+div{border-left:1px solid var(--bd)}.meta label{font-size:7px}.metricRow{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:20px 0}.metricBox{padding:17px}.metricBox strong{display:block;font-size:22px}.metricBox span{font-size:9px;color:var(--m)}.back{margin-bottom:16px}.statusgreen{color:var(--g);background:#e8f6ef}.statusyellow{color:var(--y);background:#fff3cf}.statusred{color:var(--r);background:#fcebed}.evidence{background:#f0eafd;color:var(--pu)}.healthBadge{display:inline-block;padding:4px 8px;border-radius:12px;font-size:9px;font-weight:800;margin-right:4px}.searchrow{display:flex;gap:8px;margin:15px 0}.searchrow input,.searchrow select{max-width:320px}.countline{color:var(--m);font-size:10px;margin-bottom:10px}.attentionList{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.attentionOffer{padding:14px}.attentionOffer h4{margin:0 0 6px}.issuechips{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.issuechip{padding:3px 6px;border-radius:10px;background:#edf2f7;font-size:8px}.ctaRow{display:flex;gap:8px;margin-top:14px}.sectionTitle{margin:30px 0 12px}.sectionTitle h2{margin:0}.empty{color:var(--m);font-size:11px}.productline{padding:10px 0;border-bottom:1px solid var(--bd)}.valueGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.valueCard{padding:16px}.valueCard h3{margin:7px 0}.progress{height:8px;background:#edf1f5;border-radius:5px;overflow:hidden;margin-top:8px}.progress i{display:block;height:100%;background:var(--g)}.campaignRow{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px;padding:12px;border-bottom:1px solid var(--bd);align-items:center}.campaignRow:hover{background:#fbfcfe}.valueBadge{display:inline-block;padding:4px 7px;border-radius:10px;background:#e9f1ff;color:var(--b);font-size:8px;font-weight:800}.workflow{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:14px 0}.workflow span{padding:6px 9px;border-radius:14px;background:#edf2f7;font-size:9px;font-weight:700}.workflow b{color:var(--m)}.stickyAction{display:flex;gap:8px;margin-top:12px}.valueFields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.valueFields .full{grid-column:1/-1}@media(max-width:900px){.side{position:static;width:auto}.main{margin:0}.grid,.form,.two,.domainCards,.pulse,.offeringCards,.metricRow,.attentionList,.valueGrid,.valueFields{grid-template-columns:1fr}.valueFields .full{grid-column:1}.wide,.full{grid-column:1}.content{padding:20px}}.content{font-size:14px}.hero h1{font-size:30px;line-height:1.12;letter-spacing:-.025em}.hero p{font-size:14px;line-height:1.55}.k{font-size:10px;letter-spacing:.14em}.card strong{font-size:24px}.card span{font-size:11px}.panel h2{font-size:20px;letter-spacing:-.015em}.panel h3{font-size:16px}.offeringCard h4{font-size:14px;line-height:1.3}.meta strong{font-size:14px}.meta label{font-size:8px}.btn{font-size:11px;font-weight:650}.link{font-size:inherit}.healthBadge{font-size:9px}.issuechip{font-size:9px}.side{width:252px}.main{margin-left:252px}.side button{font-size:13px;padding:9px 12px}.navgroup{font-size:9px}.domainCard h3{font-size:17px}.domainCard p{font-size:12px}.iconCircle{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:7px;background:#e9f1ff;color:var(--b);font-size:13px;margin-bottom:8px}.metricBox{border-top:3px solid var(--bd)}.metricBox.health-green{border-top-color:var(--g)}.metricBox.health-yellow{border-top-color:#d99a12}.metricBox.health-red{border-top-color:var(--r)}.statusUnknown{color:var(--m)}.panel{line-height:1.45}.attentionOffer{border-left:3px solid var(--bd)}.attentionOffer.sevHigh{border-left-color:#d98200}.attentionOffer.sevCritical{border-left-color:var(--r)}.topFunnel{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.funnelCard{padding:18px;text-align:left;position:relative}.funnelCard .step{display:inline-grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#e9f1ff;color:var(--b);font-weight:800;margin-bottom:10px}.funnelCard h3{margin:0 0 6px}.funnelCard p{font-size:11px;color:var(--m);line-height:1.45;margin:0}.subnav{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.subnav button{border:1px solid var(--bd);background:#fff;padding:8px 11px;border-radius:7px;font-size:11px;font-weight:650}.subnav button.active{background:var(--b);border-color:var(--b);color:#fff}.guidedCard{padding:17px;border-left:4px solid var(--bd)}.guidedCard.high{border-left-color:#d98200}.guidedCard.critical{border-left-color:var(--r)}.guidedCard h3{margin:0 0 5px}.completionGrid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.completionBox{padding:14px}.completionBox strong{display:block;font-size:22px}.completionBox span{font-size:9px;color:var(--m)}.nextSteps{counter-reset:steps}.nextStep{display:grid;grid-template-columns:30px 1fr auto;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid var(--bd)}.nextStep:before{counter-increment:steps;content:counter(steps);display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#e9f1ff;color:var(--b);font-size:10px;font-weight:800}.objectLink{display:inline-flex;align-items:center;gap:6px}.objectLink:after{content:'›';color:var(--b);font-size:16px}.decisionAction{display:grid;grid-template-columns:1fr 1fr;gap:12px}.adminTiles{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.adminTile{padding:18px;text-align:left}.adminTile h3{margin:8px 0}.adminTile p{font-size:11px;color:var(--m)}.compactNav .navgroup{display:none}</style></head><body><aside class="side"><div class="brand">DLR<small>Enterprise Services Portfolio</small></div><nav id="nav" class="compactNav"></nav></aside><div class="main"><header class="top" id="crumb">Portfolio Governance</header><main class="content" id="app">Loading…</main></div><script>
let M,page='overview',detail=null;
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const T=x=>'<span class="tag">'+E(x||'Unknown')+'</span>';
const HB=x=>'<span class="healthBadge status'+E(String(x||'unknown').toLowerCase())+'">'+E(x||'Unknown')+'</span>';
const navGroups=[['MAIN',[['overview','⌂ Overview'],['explore','⌕ Explore Portfolio'],['improve','◎ Improve Portfolio'],['work','✓ Decisions & Actions'],['administration','⚙ Administration']]]];
function hero(k,t,d,n=''){return '<div class="hero"><div><div class="k">'+E(k)+'</div><h1>'+E(t)+'</h1><p>'+E(d)+'</p></div>'+(n?'<div class="notice">'+E(n)+'</div>':'')+'</div>'}
function cards(a){return '<section class="grid">'+a.map(x=>'<div class="card"><strong>'+E(x[0])+'</strong><span>'+E(x[1])+'</span></div>').join('')+'</section>'}
function tab(h,r){return '<div class="table"><table><thead><tr>'+h.map(x=>'<th>'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+r.join('')+'</tbody></table></div>'}
function latest(o){return o.assessment||{}}
function show(p){page=p;detail=null;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.p===p));document.getElementById('crumb').textContent='Portfolio Management / '+p.replace(/\b\w/g,c=>c.toUpperCase());document.getElementById('app').innerHTML=({overview,explore,improve,work,administration,health,value,campaign,domains,services,offerings,products,map,queue,assess,decisions,actions,rational,admin,quality,backup}[p]||overview)();window.scrollTo({top:0})}
function bars(obj,total){return Object.entries(obj).map(([k,v])=>'<div class="barrow"><span>'+E(k)+'</span><div class="bar"><div class="fill" style="width:'+Math.round(v/(total||1)*100)+'%"></div></div><strong>'+v+'</strong></div>').join('')}
function counts(field){return M.offerings.reduce((a,o)=>{let v=latest(o)[field]||'Unknown';a[v]=(a[v]||0)+1;return a},{})}
function groupedAttention(){let by=new Map();for(const x of M.queue){if(!x.offeringId)continue;if(!by.has(x.offeringId))by.set(x.offeringId,[]);by.get(x.offeringId).push(x)}return [...by.entries()].map(([id,issues])=>({offering:M.offerings.find(o=>o.id===id),issues,severity:issues.some(x=>x.severity==='Critical')?'Critical':issues.some(x=>x.severity==='High')?'High':'Medium'})).filter(x=>x.offering).sort((a,b)=>({Critical:1,High:2,Medium:3}[a.severity]-{Critical:1,High:2,Medium:3}[b.severity]))}

let exploreTab='domains',improveTab='all',workTab='decisions',adminTab='data';
function subnav(items,current,handler){return '<div class="subnav">'+items.map(x=>'<button class="'+(x[0]===current?'active':'')+'" onclick="'+handler+'(\''+x[0]+'\')">'+E(x[1])+'</button>').join('')+'</div>'}
function explore(){const tabs=[['domains','Domains'],['services','Services'],['offerings','Offerings'],['products','Products & Systems'],['map','Relationships']];return hero('FIND AND UNDERSTAND','Explore Portfolio','Browse the hierarchy or search across portfolio objects without changing navigation areas.')+subnav(tabs,exploreTab,'setExplore')+'<div id="exploreBody">'+({domains,services,offerings,products,map}[exploreTab]||domains)().replace(/^<div class="hero">[\s\S]*?<\/div><\/div>/,'')+'</div>'}
function setExplore(x){exploreTab=x;show('explore')}
function improve(){let groups=groupedAttention(),filtered=groups;if(improveTab!=='all'){const reason={value:'Value',assessment:'assessment',technology:'technology',decision:'decision',action:'action',quality:'owner'}[improveTab];filtered=groups.filter(g=>g.issues.some(i=>(i.reason+' '+i.detail).toLowerCase().includes(reason.toLowerCase())))}const tabs=[['all','All'],['value','Value'],['assessment','Assessment'],['technology','Technology'],['decision','Decision'],['action','Action'],['quality','Data Quality']];return hero('GUIDED REVIEW FUNNEL','Improve Portfolio','Start with an offering, see every gap in one place, and continue to the next useful action.')+cards([[groups.length,'Offerings needing attention'],[M.queue.filter(x=>x.reason==='Needs decision').length,'Need decisions'],[M.queue.filter(x=>x.reason==='Overdue action').length,'Overdue actions'],[M.campaign?.complete||0,'Decision-ready complete']])+subnav(tabs,improveTab,'setImprove')+'<section class="attentionList">'+filtered.map(g=>'<article class="panel guidedCard '+g.severity.toLowerCase()+'"><div class="k">'+E(g.offering.domainName)+' / '+E(g.offering.serviceName)+'</div><h3><button class="link objectLink" onclick="openOffering(\''+g.offering.id+'\')">'+E(g.offering.name)+'</button></h3><div class="issuechips">'+g.issues.map(i=>'<span class="issuechip '+E(i.severity)+'">'+E(i.reason)+'</span>').join('')+'</div><p>'+g.issues.length+' gaps require review</p><button class="btn primary" onclick="continueReview(\''+g.offering.id+'\')">Continue review</button></article>').join('')+'</section>'}
function setImprove(x){improveTab=x;show('improve')}
function continueReview(id){openOffering(id)}
function work(){const tabs=[['decisions','Decisions'],['actions','Actions'],['outcomes','Outcomes']];let content=workTab==='decisions'?decisions():workTab==='actions'?actions():renderOutcomes();return hero('DECIDE → ACT → MEASURE','Decisions & Actions','Keep strategic choices, resulting commitments, and expected outcomes together.')+subnav(tabs,workTab,'setWork')+content.replace(/^<div class="hero">[\s\S]*?<\/div><\/div>/,'')}
function setWork(x){workTab=x;show('work')}
function renderOutcomes(){const withOutcome=M.actions.filter(a=>a.expectedOutcome);return cards([[M.decisions.length,'Recorded decisions'],[M.actions.filter(a=>!['Done','Cancelled'].includes(a.status)).length,'Open actions'],[M.actions.filter(a=>a.status==='Done').length,'Completed actions'],[withOutcome.length,'Actions with outcome']])+tab(['Offering','Action','Expected outcome','Status'],withOutcome.map(a=>'<tr><td><button class="link objectLink" onclick="openOffering(\''+a.offeringId+'\')">'+E(M.offerings.find(o=>o.id===a.offeringId)?.name||'')+'</button></td><td>'+E(a.title)+'</td><td>'+E(a.expectedOutcome)+'</td><td>'+T(a.status)+'</td></tr>'))}
function administration(){const tabs=[['data','Portfolio Data'],['value','Value Profiles'],['assessments','Assessments'],['relationships','Technology Relationships'],['quality','Data Quality'],['backup','Import / Export']];let content={data:admin,value,assessments:assess,relationships:()=>{exploreTab='map';return map()},quality,backup}[adminTab];return hero('CONTROLLED MAINTENANCE','Administration','Maintenance tools are grouped here so the main experience stays focused on portfolio decisions.')+subnav(tabs,adminTab,'setAdminArea')+(content?content().replace(/^<div class="hero">[\s\S]*?<\/div><\/div>/,''):'')}
function setAdminArea(x){adminTab=x;show('administration')}
function overview(){let h=counts('health'),d=counts('direction'),attention=groupedAttention();return hero('ENTERPRISE SERVICES PLATFORMS','Enterprise Services Portfolio','Start broad, drill into an offering, and follow the guided management cycle from understanding to measurable action.','Synthetic assessments remain visibly separated from validated evidence.')+'<section class="topFunnel"><button class="card funnelCard" onclick="show(\'explore\')"><span class="step">1</span><h3>Explore</h3><p>Navigate Domain → Service → Offering → Technology.</p></button><button class="card funnelCard" onclick="show(\'improve\')"><span class="step">2</span><h3>Improve</h3><p>Review incomplete value, assessments, technology, decisions and actions.</p></button><button class="card funnelCard" onclick="show(\'work\')"><span class="step">3</span><h3>Decide & Act</h3><p>Record decisions, assign actions and track outcomes.</p></button><button class="card funnelCard" onclick="show(\'administration\')"><span class="step">4</span><h3>Maintain</h3><p>Manage portfolio data, quality, relationships and backups.</p></button></section>'+cards([[M.domains.length,'Domains'],[M.services.length,'Services'],[M.offerings.length,'Offerings'],[M.products.length,'Products & Systems']])+'<div class="sectionTitle"><div class="k">EXPLORE</div><h2>Strategic domains</h2></div><section class="domainCards">'+M.domains.map(d=>'<button class="card domainCard" onclick="openDomain(\''+d.id+'\')"><h3>'+E(d.name)+'</h3><p>'+E(d.description||'Explore services and offerings in this domain.')+'</p><div>'+d.services.length+' services • '+d.services.flatMap(s=>s.offerings).length+' offerings</div></button>').join('')+'</section><div class="sectionTitle"><div class="k">PORTFOLIO PULSE</div><h2>Health, direction, evidence and attention</h2></div><section class="pulse"><div class="panel"><h3>Health</h3>'+bars(h,M.offerings.length)+'</div><div class="panel"><h3>Direction</h3>'+bars(d,M.offerings.length)+'</div><div class="panel"><h3>Evidence</h3>'+bars({Validated:M.assessments.filter(a=>!a.syntheticDemo&&a.status==='Validated').length,Synthetic:M.assessments.filter(a=>a.syntheticDemo).length,Missing:M.offerings.filter(o=>!o.assessment).length},M.offerings.length)+'</div><div class="panel"><h3>Attention</h3><strong style="font-size:28px">'+attention.length+'</strong><p>Offerings require review</p><div class="ctaRow"><button class="btn primary" onclick="show(\'queue\')">Review attention</button></div></div></section>'}
function health(){return hero('ASSESS • DIRECT • MEASURE','Portfolio Health','View assessment signals independently rather than hiding them inside a single score.','Use portfolio browsing to understand the hierarchy, then governance to focus action.')+'<section class="two"><div class="panel"><div class="k">HEALTH</div><h2>Offering health</h2>'+bars(counts('health'),M.offerings.length)+'</div><div class="panel"><div class="k">MATURITY</div><h2>Capability maturity</h2>'+bars(counts('maturity'),M.offerings.length)+'</div><div class="panel"><div class="k">DIRECTION</div><h2>Strategic direction</h2>'+bars(counts('direction'),M.offerings.length)+'</div><div class="panel"><div class="k">COVERAGE</div><h2>Assessment integrity</h2>'+bars({Validated:M.assessments.filter(a=>!a.syntheticDemo&&a.status==='Validated').length,Synthetic:M.assessments.filter(a=>a.syntheticDemo).length,Missing:M.offerings.filter(o=>!o.assessment).length},M.offerings.length)+'</div></section>'}

function value(){let vals=new Map(M.offeringValues.map(v=>[v.offeringId,v])),complete=M.offerings.filter(o=>{let v=vals.get(o.id);return v?.businessOutcome&&v?.valueProvided&&v?.keyMeasures}).length;return hero('WHY THE PORTFOLIO MATTERS','Value & Outcomes','Connect every service offering to the business outcome, stakeholder, criticality and measures it enables.')+cards([[complete,'Value-complete offerings'],[M.offerings.length-complete,'Need value definition'],[M.offeringValues.filter(v=>v.criticality==='Business Critical').length,'Business critical'],[M.offeringValues.filter(v=>v.strategicAlignment==='High').length,'High strategic alignment']])+'<section class="valueGrid">'+M.offerings.map(o=>{let v=vals.get(o.id)||{};return '<div class="card valueCard"><div class="k">'+E(o.domainName)+'</div><h3><button class="link" onclick="editValue(\''+o.id+'\')">'+E(o.name)+'</button></h3><p>'+E(v.businessOutcome||'Business outcome not defined')+'</p><div>'+T(v.criticality||'Unknown')+' '+T(v.strategicAlignment||'Unknown')+'</div></div>'}).join('')+'</section>'}
function editValue(id){let o=M.offerings.find(x=>x.id===id),v=M.offeringValues.find(x=>x.offeringId===id)||{};document.getElementById('crumb').textContent='Portfolio / Value / '+o.name;document.getElementById('app').innerHTML='<button class="btn back" onclick="show(\'value\')">← Value & Outcomes</button>'+hero('VALUE PROFILE',o.name,'Describe why this offering matters and how success is measured.')+'<section class="panel"><div class="valueFields"><div class="full"><label>Business outcome</label><textarea id="vbo">'+E(v.businessOutcome||'')+'</textarea></div><div><label>Customer / stakeholder</label><input id="vst" value="'+E(v.stakeholder||'')+'"></div><div><label>Criticality</label><select id="vcr">'+['Unknown','Low','Moderate','High','Business Critical'].map(x=>'<option '+(v.criticality===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="full"><label>Value provided</label><textarea id="vvp">'+E(v.valueProvided||'')+'</textarea></div><div class="full"><label>Key measures</label><textarea id="vkm">'+E(v.keyMeasures||'')+'</textarea></div><div><label>Strategic alignment</label><select id="vsa">'+['Unknown','Low','Moderate','High'].map(x=>'<option '+(v.strategicAlignment===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div><label>Review status</label><select id="vrs">'+['Needs Review','Draft','Validated'].map(x=>'<option '+(v.reviewStatus===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="full"><button class="btn primary" onclick="saveValue(\''+id+'\')">Save value profile</button></div></div></section>';window.scrollTo({top:0})}
async function saveValue(id){await api('/api/offering-values','POST',{offeringId:id,businessOutcome:vbo.value,stakeholder:vst.value,criticality:vcr.value,valueProvided:vvp.value,keyMeasures:vkm.value,strategicAlignment:vsa.value,reviewStatus:vrs.value});await reload();openOffering(id)}
function campaign(){let c=M.campaign,next=c.next,o=next?M.offerings.find(x=>x.id===next.offeringId):null;return hero('REPLACE PLACEHOLDERS WITH EVIDENCE','Assessment Campaign','Work through the portfolio systematically, one offering at a time.')+cards([[c.complete,'Complete'],[c.total-c.complete,'Remaining'],[M.assessments.filter(a=>a.syntheticDemo).length,'Synthetic'],[M.offerings.filter(o=>!o.owner).length,'Missing owner']])+(o?'<section class="panel"><div class="k">NEXT OFFERING</div><h2>'+E(o.name)+'</h2><p>'+E(o.domainName)+' / '+E(o.serviceName)+'</p><div class="progress"><i style="width:'+next.completion+'%"></i></div><p>'+next.completion+'% portfolio-complete for this offering</p><div class="stickyAction"><button class="btn primary" onclick="startAssessment(\''+o.id+'\')">Assess next</button><button class="btn" onclick="editValue(\''+o.id+'\')">Define value</button><button class="btn" onclick="openOffering(\''+o.id+'\')">Open cockpit</button></div></section>':'')+'<section class="panel"><div class="campaignRow"><strong>Offering</strong><strong>Assessment</strong><strong>Technology</strong><strong>Completion</strong></div>'+c.items.map(x=>{let o=M.offerings.find(y=>y.id===x.offeringId);return '<div class="campaignRow"><button class="link" onclick="openOffering(\''+x.offeringId+'\')">'+E(o?.name||x.offeringId)+'</button><span>'+E(x.assessmentState)+'</span><span>'+(x.technologyMapped?'Mapped':'Missing')+'</span><span>'+x.completion+'%</span></div>'}).join('')+'</section>'}
function startAssessment(id){show('assess');setTimeout(()=>{let el=document.getElementById('ao');if(el)el.value=id},0)}
function domains(){return hero('PORTFOLIO HIERARCHY','Domains','Start with a strategic domain, then drill into services, offerings and enabling technology.')+'<section class="domainCards">'+M.domains.map(d=>'<button class="card domainCard" onclick="openDomain(\''+d.id+'\')"><h3>'+E(d.name)+'</h3><p>'+E(d.description||'')+'</p>'+d.services.length+' services • '+d.services.flatMap(s=>s.offerings).length+' offerings</button>').join('')+'</section>'}
function offeringCard(o){let a=latest(o);return '<article class="card offeringCard"><div>'+HB(a.health)+(a.syntheticDemo?'<span class="healthBadge evidence">Synthetic demo</span>':'')+'</div><h4><button class="link" onclick="openOffering(\''+o.id+'\')">'+E(o.name)+'</button></h4><div class="meta"><div><label>Maturity</label><strong>'+E(a.maturity||'Unknown')+'</strong></div><div><label>Direction</label><strong>'+E(a.direction||'Unknown')+'</strong></div><div><label>Products</label><strong>'+o.products.length+'</strong></div></div></article>'}
function openDomain(id){let d=M.domains.find(x=>x.id===id);document.getElementById('crumb').textContent='Portfolio / '+d.name;document.getElementById('app').innerHTML='<button class="btn back" onclick="show(\'domains\')">← Domains</button><section class="panel" style="background:var(--n);color:white"><div class="k">STRATEGIC DOMAIN</div><h1>'+E(d.name)+'</h1><p>'+E(d.description||'')+'</p><div>'+d.services.length+' services • '+d.services.flatMap(s=>s.offerings).length+' offerings</div></section>'+d.services.map(s=>'<section class="serviceBlock"><div class="serviceHead"><div><div class="k">SERVICE</div><h2>'+E(s.name)+'</h2></div><span>'+s.offerings.length+' offerings</span></div><div class="offeringCards">'+s.offerings.map(offeringCard).join('')+'</div></section>').join('');window.scrollTo({top:0})}
function openOffering(id){let o=M.offerings.find(x=>x.id===id),a=latest(o),issues=M.queue.filter(x=>x.offeringId===id),decision=M.decisions.find(x=>x.offeringId===id&&x.status!=='Archived'),acts=M.actions.filter(x=>x.offeringId===id&&!['Done','Cancelled'].includes(x.status));document.getElementById('crumb').textContent='Portfolio / '+o.domainName+' / '+o.name;document.getElementById('app').innerHTML='<button class="btn back" onclick="openDomain(\''+o.domainId+'\')">← '+E(o.domainName)+'</button>'+hero('SERVICE OFFERING',o.name,o.description||'No validated description yet.',a.syntheticDemo?'This record currently uses a synthetic assessment.':'')+'<div class="workflow"><span>Understand</span><b>→</b><span>Assess</span><b>→</b><span>Decide</span><b>→</b><span>Act</span><b>→</b><span>Measure</span></div><section class="metricRow">'+[['Health',a.health||'Unknown'],['Maturity',a.maturity||'Unknown'],['Direction',a.direction||'Unknown'],['Risk',a.risk||'Unknown'],['Products',o.products.length]].map(x=>'<div class="panel metricBox '+(x[0]==='Health'?'health-'+String(x[1]).toLowerCase():'')+'"><strong>'+E(x[1])+'</strong><span>'+E(x[0])+'</span></div>').join('')+'</section><section class="two"><div class="panel"><div class="k">VALUE & OUTCOMES</div><h2>Why this offering matters</h2><p><strong>Business outcome:</strong> '+E(o.value?.businessOutcome||'Not defined')+'</p><p><strong>Stakeholder:</strong> '+E(o.value?.stakeholder||'Not defined')+'</p><p><strong>Criticality:</strong> '+E(o.value?.criticality||'Unknown')+'</p><p><strong>Value:</strong> '+E(o.value?.valueProvided||'Not defined')+'</p><p><strong>Measures:</strong> '+E(o.value?.keyMeasures||'Not defined')+'</p><p><strong>Strategic alignment:</strong> '+E(o.value?.strategicAlignment||'Unknown')+'</p><button class="btn" onclick="editValue(\''+id+'\')">Edit value</button></div><div class="panel"><div class="k">LATEST ASSESSMENT</div><h2>Evidence and recommendation</h2><p>'+E(a.summary||'No assessment summary.')+'</p><p><strong>Evidence:</strong> '+E(a.evidence||'Not provided')+'</p><p><strong>Risks:</strong> '+E(a.risks||'Not provided')+'</p><p><strong>Outcomes:</strong> '+E(a.measurableOutcomes||'Not provided')+'</p><div class="stickyAction"><button class="btn" onclick="startAssessment(\''+id+'\')">Assess</button><button class="btn" onclick="workTab=\'decisions\';show(\'work\')">Decide</button><button class="btn" onclick="workTab=\'actions\';show(\'work\')">Create action</button></div></div><div class="panel"><div class="k">ENABLING TECHNOLOGY</div><h2>Offering–product relationships</h2>'+(o.products.length?o.products.map(p=>'<div class="productline"><strong>'+E(p.name)+'</strong><br><small>'+E(p.relationship.role)+' • '+E(p.relationship.confidence)+' confidence</small></div>').join(''):'<p class="empty">No technology relationship mapped.</p>')+'</div><div class="panel"><div class="k">GOVERNANCE</div><h2>Attention and decision</h2><p><strong>Decision:</strong> '+E(decision?.decision||'Not recorded')+'</p><p><strong>Open actions:</strong> '+acts.length+'</p><div class="issuechips">'+issues.map(x=>'<span class="issuechip">'+E(x.reason)+'</span>').join('')+'</div><h3>Assessment history</h3>'+M.assessments.filter(x=>x.entityId===id).map(x=>'<div class="item"><strong>'+E(x.assessmentDate)+'</strong> • '+E(x.health)+' • '+E(x.maturity)+' • '+E(x.direction)+'</div>').join('')+'</div></section>';window.scrollTo({top:0})}

function editForm(type,item,fields){return '<section class="panel"><div class="k">EDIT '+E(type.toUpperCase())+'</div><div class="valueFields">'+fields.map(f=>'<div class="'+(f.wide?'full':'')+'"><label>'+E(f.label)+'</label>'+(f.options?'<select id="ed_'+f.key+'">'+f.options.map(x=>'<option '+(String(item[f.key]||'')===x?'selected':'')+'>'+E(x)+'</option>').join('')+'</select>':f.area?'<textarea id="ed_'+f.key+'">'+E(item[f.key]||'')+'</textarea>':'<input id="ed_'+f.key+'" value="'+E(item[f.key]||'')+'">')+'</div>').join('')+'<div class="full"><button class="btn primary" onclick="saveObject(\''+type+'\',\''+item.id+'\')">Save changes</button></div></div></section>'}
async function saveObject(type,id){let ids=[...document.querySelectorAll('[id^="ed_"]')],x={};for(const el of ids)x[el.id.slice(3)]=el.value;await api('/api/admin/'+type+'/'+encodeURIComponent(id),'PATCH',x);await reload();if(type==='services')openService(id);if(type==='products')openProduct(id);if(type==='relationships')openRelationship(id)}
function openService(id){let s=M.services.find(x=>x.id===id),d=M.domains.find(x=>x.id===s.domainId),offs=M.offerings.filter(o=>o.serviceId===id),rels=M.relationships.filter(r=>offs.some(o=>o.id===r.offeringId));document.getElementById('app').innerHTML='<button class="btn back" onclick="show(\'explore\')">← Explore</button>'+hero('SERVICE',s.name,s.description||'No description.')+cards([[offs.length,'Offerings'],[new Set(rels.map(r=>r.productId)).size,'Products'],[s.owner||'Unassigned','Owner'],[s.lifecycle||'Unknown','Lifecycle']])+'<section class="offeringCards">'+offs.map(offeringCard).join('')+'</section>'+editForm('services',s,[{key:'name',label:'Name'},{key:'owner',label:'Owner'},{key:'description',label:'Description',area:true,wide:true},{key:'lifecycle',label:'Lifecycle',options:['Proposed','Active','Changing','Retiring','Retired']},{key:'validationStatus',label:'Validation',options:['Needs Review','Validated']}]);window.scrollTo({top:0})}
function openProduct(id){let p=M.products.find(x=>x.id===id),rels=M.relationships.filter(r=>r.productId===id);document.getElementById('app').innerHTML='<button class="btn back" onclick="show(\'explore\')">← Explore</button>'+hero('PRODUCT / SYSTEM',p.name,p.description||'No description.')+cards([[p.vendor||'Unknown','Vendor'],[p.owner||'Unassigned','Owner'],[p.lifecycle||'Unknown','Lifecycle'],[rels.length,'Offering relationships']])+'<section class="panel"><h2>Enabled offerings</h2>'+rels.map(r=>'<div class="productline"><button class="link objectLink" onclick="openOffering(\''+r.offeringId+'\')">'+E(M.offerings.find(o=>o.id===r.offeringId)?.name||r.offeringId)+'</button><br><small><button class="link" onclick="openRelationship(\''+r.id+'\')">'+E(r.role)+' • '+E(r.confidence)+'</button></small></div>').join('')+'</section>'+editForm('products',p,[{key:'name',label:'Name'},{key:'vendor',label:'Vendor'},{key:'owner',label:'Owner'},{key:'description',label:'Description',area:true,wide:true},{key:'lifecycle',label:'Lifecycle',options:['Proposed','Active','Changing','Retiring','Retired']},{key:'validationStatus',label:'Validation',options:['Needs Review','Validated']}]);window.scrollTo({top:0})}
function openRelationship(id){let r=M.relationships.find(x=>x.id===id),o=M.offerings.find(x=>x.id===r.offeringId),p=M.products.find(x=>x.id===r.productId);document.getElementById('app').innerHTML='<button class="btn back" onclick="show(\'explore\')">← Explore</button>'+hero('OFFERING–PRODUCT RELATIONSHIP',(o?.name||'Offering')+' → '+(p?.name||'Product'),'Review why this product enables the offering and how confident the mapping is.')+cards([[r.role,'Role'],[r.confidence,'Confidence'],[r.status,'Status'],[r.health||'Unknown','Health']])+'<section class="two"><div class="panel"><h3><button class="link objectLink" onclick="openOffering(\''+r.offeringId+'\')">'+E(o?.name||'')+'</button></h3><p>Service offering</p></div><div class="panel"><h3><button class="link objectLink" onclick="openProduct(\''+r.productId+'\')">'+E(p?.name||'')+'</button></h3><p>Product / system</p></div></section>'+editForm('relationships',r,[{key:'role',label:'Relationship role'},{key:'confidence',label:'Confidence',options:['High','Medium','Low']},{key:'status',label:'Status',options:['Proposed','Active','Changing','Retired']},{key:'health',label:'Health',options:['Unknown','green','yellow','red']},{key:'owner',label:'Owner'},{key:'notes',label:'Notes',area:true,wide:true},{key:'validationStatus',label:'Validation',options:['Needs Review','Validated']}]);window.scrollTo({top:0})}
function openAssessment(id){let a=M.assessments.find(x=>x.id===id),o=M.offerings.find(x=>x.id===a.entityId);document.getElementById('app').innerHTML='<button class="btn back" onclick="adminTab=\'assessments\';show(\'administration\')">← Assessments</button>'+hero('ASSESSMENT RECORD',o?.name||a.entityId,'Point-in-time evidence record. Assessment history remains immutable; create a new assessment to supersede it.')+cards([[a.health,'Health'],[a.maturity,'Maturity'],[a.direction,'Direction'],[a.risk,'Risk']])+'<section class="two"><div class="panel"><h2>Evidence</h2><p>'+E(a.summary||'No summary')+'</p><p><strong>Evidence:</strong> '+E(a.evidence||'Not provided')+'</p><p><strong>Risks:</strong> '+E(a.risks||'Not provided')+'</p></div><div class="panel"><h2>Navigate</h2><button class="btn" onclick="openOffering(\''+a.entityId+'\')">Open offering</button> <button class="btn primary" onclick="startAssessment(\''+a.entityId+'\')">Create new assessment</button></div></section>';window.scrollTo({top:0})}
function inventory(title,type,headers,row){let list=M[type];return hero('PORTFOLIO INVENTORY',title,'Browse and search across the portfolio.')+'<div class="searchrow"><input id="find" placeholder="Filter '+E(title.toLowerCase())+'" oninput="filterTable(this.value)"></div><div class="countline">'+list.length+' records</div>'+tab(headers,list.map(row))}
function filterTable(v){v=v.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(v)?'':'none')}
function services(){return inventory('Services','services',['Service','Domain','Owner','Offerings'],s=>'<tr><td><button class="link objectLink" onclick="openService(\''+s.id+'\')">'+E(s.name)+'</button></td><td>'+E(M.domains.find(d=>d.id===s.domainId)?.name||'')+'</td><td>'+E(s.owner||'Unassigned')+'</td><td>'+M.offerings.filter(o=>o.serviceId===s.id).length+'</td></tr>')}
function offerings(){return inventory('Service Offerings','offerings',['Offering','Service','Domain','Health','Direction','Products'],o=>'<tr><td><button class="link" onclick="openOffering(\''+o.id+'\')">'+E(o.name)+'</button></td><td>'+E(o.serviceName)+'</td><td>'+E(o.domainName)+'</td><td>'+HB(latest(o).health)+'</td><td>'+T(latest(o).direction)+'</td><td>'+o.products.length+'</td></tr>')}
function products(){return inventory('Products & Systems','products',['Product','Vendor','Owner','Mapped Offerings'],p=>'<tr><td><button class="link objectLink" onclick="openProduct(\''+p.id+'\')">'+E(p.name)+'</button></td><td>'+E(p.vendor||'')+'</td><td>'+E(p.owner||'Unassigned')+'</td><td>'+M.relationships.filter(r=>r.productId===p.id).length+'</td></tr>')}
function map(){return inventory('Offering–Product Map','relationships',['Offering','Product','Role','Confidence','Status'],r=>'<tr><td><button class="link" onclick="openOffering(\''+r.offeringId+'\')">'+E(M.offerings.find(o=>o.id===r.offeringId)?.name||'')+'</button></td><td><button class="link" onclick="openProduct(\''+r.productId+'\')">'+E(M.products.find(p=>p.id===r.productId)?.name||'')+'</button></td><td><button class="link objectLink" onclick="openRelationship(\''+r.id+'\')">'+E(r.role)+'</button></td><td>'+T(r.confidence)+'</td><td>'+T(r.status)+'</td></tr>')}
function queue(){let g=groupedAttention();return hero('ATTENTION ENGINE','Governance Queue','Offerings are grouped for management review; detailed rules remain visible within each offering.')+cards([[g.length,'Offerings requiring attention'],[M.queue.filter(x=>x.severity==='Critical').length,'Critical signals'],[M.queue.filter(x=>x.reason==='Needs decision').length,'Need decisions'],[M.queue.filter(x=>x.reason==='Overdue action').length,'Overdue actions']])+'<section class="attentionList">'+g.map(x=>'<div class="panel attentionOffer sev'+E(x.severity)+'"><h4><button class="link" onclick="openOffering(\''+x.offering.id+'\')">'+E(x.offering.name)+'</button></h4><div>'+E(x.offering.domainName)+' / '+E(x.offering.serviceName)+'</div><div class="issuechips">'+x.issues.map(i=>'<span class="issuechip '+E(i.severity)+'">'+E(i.reason)+'</span>').join('')+'</div><p>'+x.issues.length+' governance gaps</p></div>').join('')+'</section>'}

function assess(){let opts=M.offerings.map(o=>'<option value="'+E(o.id)+'">'+E(o.domainName+' / '+o.name)+'</option>').join('');return hero('POINT-IN-TIME EVIDENCE','Assessment Workspace','Create a new assessment without overwriting history.')+'<section class="panel"><div class="form"><div class="wide"><label>Offering</label><select id="ao"><option value="">Choose…</option>'+opts+'</select></div><div><label>Health</label><select id="ah"><option>green</option><option>yellow</option><option>red</option></select></div><div><label>Maturity</label><select id="am"><option>Emerging</option><option>Developing</option><option>Established</option><option>Leading</option></select></div><div><label>Direction</label><select id="ad"><option>Invest</option><option>Improve</option><option>Maintain</option><option>Consolidate</option><option>Retire</option></select></div><div><label>Risk</label><select id="ar"><option>Unknown</option><option>Low</option><option>Moderate</option><option>High</option><option>Critical</option></select></div><div class="wide"><label>Summary</label><textarea id="asu"></textarea></div><div><label>Owner</label><input id="aown"></div><div><label>Assessor</label><input id="aas"></div><div class="full"><button class="btn primary" onclick="addAssessment()">Save assessment</button></div></div></section>'+tab(['Offering','Date','Health','Maturity','Direction','Risk','State'],M.assessments.map(a=>'<tr><td><button class="link objectLink" onclick="openAssessment(\''+a.id+'\')">'+E(M.offerings.find(o=>o.id===a.entityId)?.name||a.entityId)+'</button></td><td>'+E(a.assessmentDate)+'</td><td>'+HB(a.health)+'</td><td>'+T(a.maturity)+'</td><td>'+T(a.direction)+'</td><td>'+T(a.risk)+'</td><td>'+T(a.syntheticDemo?'Synthetic':a.status)+'</td></tr>'))}
async function addAssessment(){let x={entityId:document.getElementById('ao').value,health:ah.value,maturity:am.value,direction:ad.value,risk:ar.value,summary:asu.value,owner:aown.value,assessor:aas.value,status:'Submitted',syntheticDemo:false};if(!x.entityId)return alert('Choose an offering');await api('/api/assessments','POST',x);await reload();show('assess')}
function decisions(){let opts=M.offerings.map(o=>'<option value="'+E(o.id)+'">'+E(o.domainName+' / '+o.name)+'</option>').join('');return hero('ASSESS → DECIDE → ACT','Decision Register','Capture explicit direction, rationale, ownership and investment implication.')+'<section class="panel"><div class="form"><div><label>Offering</label><select id="do"><option value="">Choose…</option>'+opts+'</select></div><div><label>Decision</label><select id="dd"><option>Invest</option><option>Improve</option><option>Maintain</option><option>Consolidate</option><option>Retire</option></select></div><div><label>Owner</label><input id="down"></div><div><label>Status</label><select id="ds"><option>Proposed</option><option>Approved</option></select></div><div class="wide"><label>Rationale</label><textarea id="dr"></textarea></div><div><label>Target date</label><input id="dt" type="date"></div><div><label>Investment</label><select id="di"><option>Unknown</option><option>Increase</option><option>Neutral</option><option>Reduce</option><option>Avoid</option></select></div><div class="full"><button class="btn primary" onclick="addDecision()">Record decision</button></div></div></section>'+tab(['Decision','Offering','Owner','Target','Investment','Status'],M.decisions.map(d=>'<tr><td>'+T(d.decision)+'</td><td>'+E(M.offerings.find(o=>o.id===d.offeringId)?.name||'')+'</td><td>'+E(d.owner)+'</td><td>'+E(d.targetDate)+'</td><td>'+T(d.investmentImplication)+'</td><td>'+T(d.status)+'</td></tr>'))}
async function addDecision(){let x={offeringId:document.getElementById('do').value,decision:dd.value,owner:down.value,status:ds.value,rationale:dr.value,targetDate:dt.value,investmentImplication:di.value};if(!x.offeringId)return alert('Choose an offering');await api('/api/decisions','POST',x);await reload();show('decisions')}
function actions(){let opts=M.offerings.map(o=>'<option value="'+E(o.id)+'">'+E(o.name)+'</option>').join('');return hero('ACT & MEASURE','Action Register','Turn decisions into owned, dated and measurable work.')+'<section class="panel"><div class="form"><div class="wide"><label>Title</label><input id="at"></div><div><label>Offering</label><select id="aof"><option value="">None</option>'+opts+'</select></div><div><label>Owner</label><input id="aow"></div><div><label>Due</label><input id="adu" type="date"></div><div><label>Priority</label><select id="ap"><option>Medium</option><option>High</option><option>Critical</option><option>Low</option></select></div><div class="wide"><label>Expected outcome</label><textarea id="ae"></textarea></div><div class="full"><button class="btn primary" onclick="addAction()">Add action</button></div></div></section>'+tab(['Action','Offering','Owner','Due','Priority','Status'],M.actions.map(a=>'<tr><td>'+E(a.title)+'</td><td>'+E(M.offerings.find(o=>o.id===a.offeringId)?.name||'')+'</td><td>'+E(a.owner)+'</td><td>'+E(a.dueDate)+'</td><td>'+T(a.priority)+'</td><td>'+T(a.status)+'</td></tr>'))}
async function addAction(){if(!at.value)return alert('Title required');await api('/api/actions','POST',{title:at.value,offeringId:aof.value,owner:aow.value,dueDate:adu.value,priority:ap.value,expectedOutcome:ae.value});await reload();show('actions')}
function rational(){let r=M.rationalization,box=(t,a,f)=>'<div class="panel"><h3>'+E(t)+' ('+a.length+')</h3><div class="list">'+a.slice(0,30).map(f).join('')+'</div></div>';return hero('TECHNOLOGY RATIONALIZATION','Technology Rationalization','Find unused technology, coverage gaps and weak mappings.')+'<section class="grid">'+box('Unmapped products',r.unmappedProducts,x=>'<div class="item"><button class="link objectLink" onclick="openProduct(\''+x.id+'\')">'+E(x.name)+'</button></div>')+box('Unmapped offerings',r.unmappedOfferings,x=>'<div class="item"><button class="link objectLink" onclick="openOffering(\''+x.id+'\')">'+E(x.name)+'</button></div>')+box('Low-confidence mappings',r.lowConfidence,x=>'<div class="item"><button class="link objectLink" onclick="openRelationship(\''+x.id+'\')">'+E(x.role)+' • '+E(x.confidence)+'</button></div>')+'</section>'}
let adminType='services';function admin(){let types=['services','offerings','products','relationships'],list=M[adminType],form='';if(adminType==='services')form='<div><label>Name</label><input id="en"></div><div><label>Domain</label><select id="ep">'+M.domains.map(x=>'<option value="'+E(x.id)+'">'+E(x.name)+'</option>').join('')+'</select></div><div><label>Owner</label><input id="eo"></div>';if(adminType==='offerings')form='<div><label>Name</label><input id="en"></div><div><label>Service</label><select id="ep">'+M.services.map(x=>'<option value="'+E(x.id)+'">'+E(x.name)+'</option>').join('')+'</select></div><div><label>Owner</label><input id="eo"></div>';if(adminType==='products')form='<div><label>Name</label><input id="en"></div><div><label>Vendor</label><input id="ev"></div><div><label>Owner</label><input id="eo"></div>';if(adminType==='relationships')form='<div><label>Offering</label><select id="eof">'+M.offerings.map(x=>'<option value="'+E(x.id)+'">'+E(x.name)+'</option>').join('')+'</select></div><div><label>Product</label><select id="epr">'+M.products.map(x=>'<option value="'+E(x.id)+'">'+E(x.name)+'</option>').join('')+'</select></div><div><label>Role</label><input id="ero" value="Supporting platform"></div><div><label>Confidence</label><select id="eco"><option>Medium</option><option>High</option><option>Low</option></select></div>';return hero('SQLITE MASTER DATA','Portfolio Administration','Create and archive portfolio master records.')+'<div class="tabs">'+types.map(x=>'<button class="'+(x===adminType?'active':'')+'" onclick="adminType=\''+x+'\';show(\'admin\')">'+E(x)+'</button>').join('')+'</div><section class="panel"><div class="form">'+form+'<div class="full"><button class="btn primary" onclick="addEntity()">Create</button></div></div></section>'+tab(['Record','Details','Action'],list.map(x=>'<tr><td>'+E(x.name||x.id)+'</td><td>'+E(x.owner||x.role||x.vendor||'')+'</td><td><button class="btn" onclick="archiveEntity(\''+x.id+'\')">Archive</button></td></tr>'))}
async function addEntity(){let x={};if(adminType==='services')x={name:en.value,domainId:ep.value,owner:eo.value};if(adminType==='offerings')x={name:en.value,serviceId:ep.value,owner:eo.value};if(adminType==='products')x={name:en.value,vendor:ev.value,owner:eo.value};if(adminType==='relationships')x={offeringId:eof.value,productId:epr.value,role:ero.value,confidence:eco.value};await api('/api/admin/'+adminType,'POST',x);await reload();show('admin')}
async function archiveEntity(id){if(!confirm('Archive this record?'))return;await api('/api/admin/'+adminType+'/'+encodeURIComponent(id),'DELETE');await reload();show('admin')}
function quality(){return hero('DATA FOUNDATION','Data Quality','See structural gaps without overwhelming the primary portfolio experience.')+cards([[M.rationalization.unmappedOfferings.length,'Unmapped offerings'],[M.rationalization.unmappedProducts.length,'Unmapped products'],[M.rationalization.lowConfidence.length,'Low-confidence mappings'],[M.offerings.filter(o=>!o.owner).length,'Offerings missing owner']])}
function backup(){return hero('PORTABILITY','Backup / Restore','Export the entire portfolio or preview and merge a JSON backup.')+'<section class="two"><div class="panel"><h3>Export</h3><p>Download portfolio, assessments, actions and decisions.</p><a class="btn primary" href="/api/export/portfolio" download>Download backup</a></div><div class="panel"><h3>Restore / Merge</h3><textarea id="imp" placeholder="Paste exported JSON"></textarea><p><button class="btn" onclick="previewImport()">Preview</button> <button class="btn primary" onclick="mergeImport()">Merge</button></p><div id="ipr"></div></div></section>'}
async function previewImport(){let x;try{x=JSON.parse(imp.value)}catch(e){return alert('Invalid JSON')}let r=await api('/api/import/preview','POST',x);ipr.innerHTML='<pre>'+E(JSON.stringify(r,null,2))+'</pre>'}
async function mergeImport(){let x;try{x=JSON.parse(imp.value)}catch(e){return alert('Invalid JSON')}await api('/api/import','POST',x);await reload();show('backup')}
async function api(u,m='GET',x){let r=await fetch(u,{method:m,headers:m==='GET'?{}:{'Content-Type':'application/json'},body:m==='GET'?undefined:JSON.stringify(x||{})});let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
async function reload(){M=await api('/api/view-model')}
document.getElementById('nav').innerHTML=navGroups.map(g=>'<div class="navgroup">'+g[0]+'</div>'+g[1].map(x=>'<button data-p="'+x[0]+'" onclick="show(\''+x[0]+'\')">'+x[1]+'</button>').join('')).join('');reload().then(()=>show('overview')).catch(e=>app.innerHTML='<div class="notice">'+E(e.message)+'</div>');
</script></body></html>`;
const server=http.createServer((req,res)=>{const u=new URL(req.url,`http://${req.headers.host||'localhost'}`),p=u.pathname,fail=e=>json(res,400,{error:e.message});if(p==='/healthz')return json(res,200,{status:'ok',service:'enterprise-services-portfolio'});if(p==='/api/view-model')return json(res,200,vm());if(p==='/api/storage')return json(res,200,store.info());if(p==='/api/governance-queue')return json(res,200,store.queue());if(p==='/api/rationalization')return json(res,200,store.rationalization());if(p==='/api/decisions'&&req.method==='GET')return json(res,200,store.decisions());if(p==='/api/decisions'&&req.method==='POST')return body(req).then(x=>json(res,201,store.createDecision(x))).catch(fail);if(p==='/api/actions'&&req.method==='POST')return body(req).then(x=>json(res,201,store.createAction(x))).catch(fail);if(p==='/api/assessments'&&req.method==='POST')return body(req).then(x=>json(res,201,store.createAssessment(x))).catch(fail);let m=p.match(/^\/api\/admin\/(services|offerings|products|relationships)(?:\/([^/]+))?$/);if(m&&req.method==='PATCH')return body(req).then(x=>json(res,200,store.updateEntity(m[1],decodeURIComponent(m[2]),x))).catch(fail);if(m&&req.method==='POST')return body(req).then(x=>json(res,201,store.createEntity(m[1],x))).catch(fail);if(m&&req.method==='DELETE')return json(res,200,{archived:store.archive(m[1],decodeURIComponent(m[2]))});if(p==='/api/data-enhancements')return json(res,200,{mapping:store.rationalization(),storage:store.info()});if(p==='/api/offering-values'&&req.method==='GET')return json(res,200,store.offeringValues());if(p==='/api/offering-values'&&req.method==='POST')return body(req).then(x=>json(res,200,store.saveOfferingValue(x))).catch(fail);if(p==='/api/assessment-campaign')return json(res,200,store.assessmentCampaign());if(p==='/api/export/portfolio')return json(res,200,{exportedAt:new Date().toISOString(),portfolio:store.portfolio(),assessments:store.assessments(),actions:store.actions(),decisions:store.decisions(),offeringValues:store.offeringValues()});if(p==='/api/import/preview'&&req.method==='POST')return body(req).then(x=>{const s=x.portfolio||x,e=store.portfolio(),out={};for(const t of ['domains','services','offerings','products','relationships']){let ids=new Set(e[t].map(y=>y.id)),a=s[t]||[];out[t]={incoming:a.length,create:a.filter(y=>!ids.has(y.id)).length,possibleUpdate:a.filter(y=>ids.has(y.id)).length}}json(res,200,out)}).catch(fail);if(p==='/api/import'&&req.method==='POST')return body(req).then(x=>{let s=x.portfolio||x,c=0;for(const t of ['services','offerings','products','relationships'])for(const y of s[t]||[])try{store.createEntity(t,y);c++}catch{}json(res,200,{created:c})}).catch(fail);if(p==='/')return res.end(HTML);json(res,404,{error:'Not found'})});process.on('SIGINT',()=>{store.close();process.exit()});server.listen(PORT,'0.0.0.0',()=>console.log(JSON.stringify({message:'Portfolio governance started',port:PORT})));
